class Solution:
    def lengthOfLastWord(self, s: str) -> int:
        i = len(s) - 1
        # 跳過尾端空格
        while i >= 0 and s[i] == ' ':
            i -= 1
        length = 0
        # 往左數最後一個單詞的字元
        while i >= 0 and s[i] != ' ':
            length += 1
            i -= 1
        return length

