// 從尾端往前：先跳過空白，再數字元
// 時間複雜度: O(n)，空間複雜度: O(1)
int lengthOfLastWord(char* s) {
    int i = strlen(s) - 1, len = 0;
    while (i >= 0 && s[i] == ' ') i--;
    while (i >= 0 && s[i] != ' ') {
        len++;
        i--;
    }
    return len;
}

